/**
 * 离线确定性 Provider（原测试替身）：为单测 / 评测（eval）提供零网络的脚本化输出。
 * - 剧本按角色撰写，转交行动态渲染（renderHandoff），防回环（只选未发言者）；
 * - 首回合脚本化 tool_calls（write_todos + write_file），驱动交付件闭环断言；
 * - M24：按工具白名单（= 范式门控的投影）输出 write_plan / submit_review / 派发波 update_plan_step；
 * - mock 模式下运行器与单测均复用本实现；运行时装配仅在 LLM_MOCK=true 显式开启时引用
 *   （E2E / 离线演示；默认生产走真实模型，非自动降级）。
 */
