// 兼容既有导入路径（测试 / 装配方从 mock.js 取用）
export { textOfContent }

/** 每片文本的模拟延时（测试可通过构造参数调小为 0） */
const CHUNK_SIZE = 7

/** M4：用量估算（测试替身不接真实 tokenizer：字符数近似，断言用） */
function estimateUsage(req: ChatRequest, produced: string): LlmUsage {
  const promptChars =
    req.system.length + req.messages.reduce((sum, m) => sum + textOfContent(m.content).length, 0)
  return {
    promptTokens: Math.max(1, Math.round(promptChars / 1.6)),
    completionTokens: Math.max(1, Math.round(produced.length / 1.6)),
  }
}

const TOPICS = [
  '登录',
  '注册',
  '支付',
  '搜索',
  '消息',
  '上传',
  '权限',
  '评论',
  '收藏',
  '导出',
  '增长',
  '内容',
  '客户',
  '财务',
  '合同',
  '报税',
  '税务',
  '求职',
  '购房',
  '长辈',
  '前程',
  '家装', // M65-A：家装设计工作室（无既有语料碰撞——2026-09-19 全仓扫描）
  '阳宅', // M66-A：堪舆阳宅（无既有语料碰撞——全仓扫描）
]

export function detectTopic(userText: string): string {
  for (const t of TOPICS) {
    if (userText.includes(t)) return t
  }
  return '通用'
}

/** 运行时动态转交（§7.3）：优先 handoff 且在场未发言者，其次会话成员顺序，无人可接 → 交还用户 */
export function pickNext(
  meta: { agentId: string; participantIds: string[]; spokenAgentIds?: string[] },
  preferred: string[],
): string | null {
  const spoken = new Set(meta.spokenAgentIds ?? [])
  const eligible = (id: string) => id !== meta.agentId && meta.participantIds.includes(id) && !spoken.has(id)
  const fromPreferred = preferred.find(eligible)
  if (fromPreferred) return fromPreferred
  const fromMembers = meta.participantIds.find(eligible)
  return fromMembers ?? null
}

interface ScriptContext {
  topic: string
  userText: string
  /** 本回合产出的交付件路径（脚本化工具阶段写入） */
  artifactPath?: string
  /** 用户拍了拍（轻量提醒消息，不进入正式需求） */
  isNudge: boolean
}

const NOUNS: Record<string, string> = {
  登录: '登录',
  注册: '注册',
  支付: '支付',
  搜索: '搜索',
  消息: '消息',
  上传: '上传',
  权限: '权限',
  评论: '评论',
  收藏: '收藏',
  导出: '导出',
  通用: '这个需求',
  前程: '前程',
}

type RoleScript = (ctx: ScriptContext) => string[]

function topicName(ctx: ScriptContext): string {
  return NOUNS[ctx.topic] ?? ctx.topic
}

/** MM-DD（今天 + offset 天；timeline 演示用，今天一条可触发「今天」高亮） */
function dateMMDD(offset: number): string {
  const d = new Date(Date.now() + offset * 86_400_000)
  return `${String(d.getMonth() + 1).padStart(2, '0')}-${String(d.getDate()).padStart(2, '0')}`
}

