/** 主持人收尾纪要（minutes 三栏；待办 owner 取在场非主持人前两位；块首尾空行保持独立成段） */
function meetingMinutes(hostId: string, participantIds: string[], labels?: Record<string, string>): string[] {
  const title = MEETING_ROUNDS[hostId]?.title ?? '例会'
  const others = participantIds.filter((id) => id !== hostId)
  const nameOf = (id: string | undefined): string =>
    id ? (labels?.[id] ?? DISPLAY_NAMES[baseAgentId(id)] ?? id) : '各成员'
  const a = others[0]
  const b = others[1] ?? others[0]
  return [
    '',
    `::: minutes ${title}纪要`,
    '- 决议 | 各线汇报已收敛：本周结论以经营简报为准，数字口径统一按财务版本',
    '- 决议 | 下次例会前各线先对齐数据口径，避免复盘偏差',
    `- 待办 | @${nameOf(a)} 按本周结论更新执行排期并同步工作区`,
    `- 待办 | @${nameOf(b)} 补齐数据口径说明与风险备注`,
    '- 风险 | 关键指标若未回暖，优先收缩投入并把结论带回下次例会',
    ':::',
    '',
  ]
}

