/** 行程走查（日期为动态相对值：昨天 / 今天 / 明天；供 E2E 今天高亮断言） */
function isoDayOf(offset: number): string {
  const d = new Date()
  d.setDate(d.getDate() + offset)
  const y = d.getFullYear()
  const m = String(d.getMonth() + 1).padStart(2, '0')
  const day = String(d.getDate()).padStart(2, '0')
  return `${y}-${m}-${day}`
}

